#include <stdio.h>
#include <time.h>
#define N (16*1024*1024)
static int a[N];
int main(void){
  for(int i=0;i<N;i++) a[i]=i;
  volatile long s=0;
  clock_t t0=clock();
  for(int it=0;it<4;it++) for(int i=0;i<N;i+=1) s+=a[i];
  clock_t t1=clock();
  for(int it=0;it<4;it++) for(int i=0;i<N;i+=16) s+=a[i];
  clock_t t2=clock();
  printf("seq %.3fs stride16 %.3fs s=%ld\n", (double)(t1-t0)/CLOCKS_PER_SEC, (double)(t2-t1)/CLOCKS_PER_SEC, s);
  return 0;
}
